/**
 * Photos: the family's home photos and videos, straight off the NAS.
 *
 * The share is mounted read-only into Home Assistant as /media/photos
 * (config/bin/ha-photo-mount.sh) and declared as the media_dirs source
 * `photos`, so everything here goes through HA's own media_source API: listing
 * via `media_source/browse_media`, and each file via a signed, expiring URL
 * from `media_source/resolve_media`. Nothing is served from /local, which HA
 * exposes without a login.
 *
 * Thumbnails are QNAP's, generated by Multimedia Console into a hidden
 * `.@__thumb` folder beside each photo: `s100<name>` (~3 KB), `default<name>`
 * (~25 KB, the grid size) and `s800<name>`. HA's browse hides that folder but
 * will still resolve a file inside it, so the grid asks for
 * `<folder>/.@__thumb/default<name>` and falls back to a labelled placeholder
 * while QNAP is still working through the library. Originals are only ever
 * loaded one at a time, in the viewer.
 *
 * One timeline, newest month first, rather than folders: see buildIndex for
 * how the several differently-organised trees on the share are merged by
 * month, and loadMonth for the per-month fetch that runs only on scroll.
 */
import { useCallback, useEffect, useMemo, useRef, useState, type CSSProperties } from 'react';
import type { Hass } from '../ha/types';

/** The websocket connection: unlike `hass`, it keeps its identity across state updates. */
type Conn = Hass['connection'];

const ROOT = 'media-source://media_source/photos';

type Item = { id: string; title: string; cls: string; dir: boolean };

type BrowseResult = {
  title: string;
  children?: Array<{ media_content_id: string; title: string; media_class: string; can_expand: boolean }>;
};

const C = {
  text: 'var(--wt-text)', dim: 'var(--wt-dim)', faint: 'var(--wt-faint)', gold: 'var(--wt-gold)',
  line: 'var(--wt-line)', glass: 'var(--wt-glass)', radius: 'var(--wt-radius)',
};

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August',
  'September', 'October', 'November', 'December'];

const nameOf = (id: string) => decodeURIComponent(id.slice(id.lastIndexOf('/') + 1));
const parentOf = (id: string) => id.slice(0, id.lastIndexOf('/'));

/* Formats a browser can show or play itself. Anything else - Canon RAW, HEIC
   outside Safari, TIFF, MPEG-2, AVCHD - gets QNAP's s800 preview instead. */
const SHOWABLE = /\.(jpe?g|png|gif|webp|bmp|avif)$/i;
const PLAYABLE = /\.(mp4|m4v|mov|webm)$/i;

/* ------------------------------------------------------------------ data */

const browseCache = new Map<string, Promise<Item[]>>();

function browse(conn: Conn, id: string): Promise<Item[]> {
  let p = browseCache.get(id);
  if (!p) {
    p = conn.sendMessagePromise<BrowseResult>({ type: 'media_source/browse_media', media_content_id: id })
      .then((r) => (r.children ?? [])
        .filter((c) => c.can_expand || c.media_class === 'image' || c.media_class === 'video')
        .map((c) => ({ id: c.media_content_id, title: c.title, cls: c.media_class, dir: c.can_expand })));
    // A failed listing must not be cached, or one network blip hides a folder
    // until the page is reloaded.
    p.catch(() => browseCache.delete(id));
    browseCache.set(id, p);
  }
  return p;
}

/* Signed URLs last a day; reuse them for an hour so scrolling back over a
   month does not re-ask for every tile. */
const urlCache = new Map<string, { url: Promise<string>; at: number }>();

function resolveUrl(conn: Conn, id: string): Promise<string> {
  const hit = urlCache.get(id);
  if (hit && Date.now() - hit.at < 3600_000) return hit.url;
  const url = conn
    .sendMessagePromise<{ url: string }>({ type: 'media_source/resolve_media', media_content_id: id, expires: 86400 })
    .then((r) => r.url);
  url.catch(() => urlCache.delete(id));
  urlCache.set(id, { url, at: Date.now() });
  return url;
}

const thumbId = (item: Item, size: 'default' | 's800' = 'default') =>
  `${parentOf(item.id)}/.@__thumb/${size}${nameOf(item.id)}`;

/* ---------------------------------------------------------------- pieces */

function PlayBadge() {
  return (
    <svg viewBox="0 0 24 24" width="26" height="26" aria-hidden="true"
      style={{ position: 'absolute', left: '50%', top: '50%', transform: 'translate(-50%,-50%)', filter: 'drop-shadow(0 1px 4px rgba(0,0,0,.7))' }}>
      <circle cx="12" cy="12" r="11" fill="rgba(0,0,0,.45)" />
      <path d="M9.5 7.5v9l7-4.5z" fill="#fff" />
    </svg>
  );
}

/** One grid tile: resolves its thumbnail only once it scrolls into view. */
function Tile({ conn, item, onOpen, size }: { conn: Conn; item: Item; onOpen: () => void; size: number }) {
  const ref = useRef<HTMLButtonElement>(null);
  const [src, setSrc] = useState<string | null>(null);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return undefined;
    let live = true;
    const io = new IntersectionObserver((entries) => {
      if (!entries.some((e) => e.isIntersecting)) return;
      io.disconnect();
      resolveUrl(conn, thumbId(item)).then((u) => { if (live) setSrc(u); }, () => { if (live) setFailed(true); });
    }, { rootMargin: '400px' });
    io.observe(el);
    return () => { live = false; io.disconnect(); };
  }, [conn, item]);

  const video = item.cls === 'video';
  return (
    <button
      ref={ref} type="button" onClick={onOpen} title={item.title} aria-label={`${video ? 'Video' : 'Photo'} ${item.title}`}
      style={{
        position: 'relative', width: '100%', aspectRatio: '1', padding: 0, border: 'none', borderRadius: 8,
        overflow: 'hidden', cursor: 'pointer', background: 'rgba(255,255,255,0.05)',
      }}
    >
      {src && !failed ? (
        <img
          src={src} alt="" loading="lazy" decoding="async" onError={() => setFailed(true)}
          style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }}
        />
      ) : (
        <span style={{
          position: 'absolute', inset: 0, display: 'grid', placeItems: 'center', padding: 6,
          fontSize: size < 100 ? 9 : 10.5, color: C.faint, textAlign: 'center', wordBreak: 'break-all', lineHeight: 1.2,
        }}>{failed ? item.title : ''}</span>
      )}
      {video && <PlayBadge />}
    </button>
  );
}

/** Full-screen viewer with previous / next, arrow keys and Escape. */
function Viewer({ conn, items, index, onIndex, onClose }: {
  conn: Conn; items: Item[]; index: number; onIndex: (i: number) => void; onClose: () => void;
}) {
  const item = items[index];
  const name = nameOf(item.id);
  const video = item.cls === 'video';
  const native = video ? PLAYABLE.test(name) : SHOWABLE.test(name);
  const [url, setUrl] = useState<string | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [openUrl, setOpenUrl] = useState<string | null>(null);

  useEffect(() => {
    let live = true;
    setUrl(null); setPreview(null); setOpenUrl(null);
    // The s800 preview arrives first and fast; the original replaces it when
    // (and if) the browser can show it.
    resolveUrl(conn, thumbId(item, 's800')).then((u) => live && setPreview(u), () => undefined);
    resolveUrl(conn, item.id).then((u) => { if (!live) return; setOpenUrl(u); if (native) setUrl(u); }, () => undefined);
    return () => { live = false; };
  }, [conn, item, native]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
      else if (e.key === 'ArrowRight' && index < items.length - 1) onIndex(index + 1);
      else if (e.key === 'ArrowLeft' && index > 0) onIndex(index - 1);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [index, items.length, onClose, onIndex]);

  const navBtn = (dir: -1 | 1): CSSProperties => ({
    position: 'absolute', top: '50%', [dir < 0 ? 'left' : 'right']: 10, transform: 'translateY(-50%)',
    width: 44, height: 64, borderRadius: 10, border: 'none', cursor: 'pointer', fontSize: 28,
    background: 'rgba(0,0,0,.45)', color: '#fff',
  });

  return (
    <div
      role="dialog" aria-modal="true" aria-label={item.title}
      onClick={onClose}
      style={{ position: 'fixed', inset: 0, zIndex: 50, background: 'rgba(5,6,8,.94)', display: 'flex', flexDirection: 'column' }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '12px 16px', color: '#ddd', fontSize: 13 }}
        onClick={(e) => e.stopPropagation()}>
        <span style={{ flex: 1, minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
          {item.title}
        </span>
        <span style={{ color: '#999' }}>{`${index + 1} / ${items.length}`}</span>
        {openUrl && (
          <a href={openUrl} target="_blank" rel="noreferrer" style={{ color: '#d3b06e', textDecoration: 'none' }}>
            Original
          </a>
        )}
        <button type="button" onClick={onClose} aria-label="Close"
          style={{ border: 'none', background: 'none', color: '#fff', fontSize: 26, cursor: 'pointer', lineHeight: 1 }}>&times;</button>
      </div>

      <div style={{ position: 'relative', flex: 1, minHeight: 0, display: 'grid', placeItems: 'center' }}
        onClick={(e) => e.stopPropagation()}>
        {video && native && url ? (
          <video src={url} controls autoPlay playsInline style={{ maxWidth: '100%', maxHeight: '100%' }} />
        ) : (url || preview) ? (
          <img src={url ?? preview ?? undefined} alt={item.title}
            style={{ maxWidth: '100%', maxHeight: '100%', objectFit: 'contain' }} />
        ) : (
          <span style={{ color: '#888', fontSize: 13 }}>Loading&hellip;</span>
        )}
        {!native && (
          <div style={{ position: 'absolute', bottom: 14, left: 0, right: 0, textAlign: 'center', fontSize: 12, color: '#aaa' }}>
            {video
              ? 'This video format will not play in a browser — use Original to download it.'
              : 'Showing a preview — the original is a RAW/HEIC file your browser cannot display.'}
          </div>
        )}
        {index > 0 && <button type="button" aria-label="Previous" style={navBtn(-1)} onClick={() => onIndex(index - 1)}>&lsaquo;</button>}
        {index < items.length - 1 && <button type="button" aria-label="Next" style={navBtn(1)} onClick={() => onIndex(index + 1)}>&rsaquo;</button>}
      </div>
    </div>
  );
}

/* ------------------------------------------------------------ the index */

/*
 * One timeline, not folders. The library is spread over several trees that
 * each encode the month differently:
 *
 *   2014/09/...                         year -> MM
 *   Whalen Photos/2014/September 2014/  year -> "Month YYYY"
 *   Google Photos/2014/09/              year -> MM
 *   Whalen Videos/Whalen Family Movies/Camcorder April 2009 thru July 8 2010
 *
 * So the index is built from folder NAMES only - about fifty listings, no
 * per-file work - and every folder that names a month lands in that month's
 * bucket. A month's files are fetched only when its section nears the screen.
 * Anything that never names a date goes in a final Undated section.
 */

const MONTH_NAMES = MONTHS.map((m) => m.toLowerCase());
const MONTH_RE = new RegExp(`\\b(${MONTH_NAMES.join('|')}|${MONTH_NAMES.map((m) => m.slice(0, 3)).join('|')})\\.?\\s+(?:\\d{1,2},?\\s+)?((?:19|20)\\d{2})\\b`, 'i');

type Bucket = { key: string; folders: string[] };

function monthFromName(name: string, year: string | null): string | null {
  if (year && /^(0[1-9]|1[0-2])$/.test(name)) return `${year}-${name}`;
  const m = MONTH_RE.exec(name);
  if (m) {
    const w = m[1].toLowerCase().slice(0, 3);
    const i = MONTH_NAMES.findIndex((n) => n.startsWith(w));
    if (i >= 0) return `${m[2]}-${String(i + 1).padStart(2, '0')}`;
  }
  return null;
}

async function buildIndex(conn: Conn): Promise<Bucket[]> {
  const buckets = new Map<string, string[]>();
  const add = (key: string, id: string) => {
    const list = buckets.get(key) ?? [];
    list.push(id);
    buckets.set(key, list);
  };

  async function walk(id: string, year: string | null, depth: number): Promise<void> {
    const kids = await browse(conn, id).catch(() => [] as Item[]);
    const files = kids.filter((k) => !k.dir);
    // Loose files sit in whatever this folder dates to, or Undated.
    if (files.length) add(year ? `${year}-00` : 'undated', id);
    await Promise.all(kids.filter((k) => k.dir).map(async (d) => {
      const month = monthFromName(d.title, year);
      if (month) { add(month, d.id); return; }
      const y = /^((?:19|20)\d{2})(?:\s*-\s*(?:19|20)\d{2})?$/.exec(d.title);
      if (y) return walk(d.id, y[1], depth + 1);
      if (depth < 3) return walk(d.id, year, depth + 1);
      add(year ? `${year}-00` : 'undated', d.id);
    }));
  }

  await walk(ROOT, null, 0);
  return [...buckets.entries()]
    .map(([key, folders]) => ({ key, folders }))
    .sort((a, b) => (a.key === 'undated' ? 1 : b.key === 'undated' ? -1 : b.key.localeCompare(a.key)));
}

/* Some cameras and phones put the capture time in the file name; when they
   do, it orders a month far better than the name itself. */
function stampOf(name: string): number | null {
  const d = /((?:19|20)\d{2})[-_.]?(0[1-9]|1[0-2])[-_.]?([0-2]\d|3[01])[ _T-]?(?:([01]\d|2[0-3])[.:\-_]?([0-5]\d)[.:\-_]?([0-5]\d))?/.exec(name);
  if (d) return Date.UTC(+d[1], +d[2] - 1, +d[3], +(d[4] ?? 0), +(d[5] ?? 0), +(d[6] ?? 0));
  const ms = /^(1[2-7]\d{11})\b/.exec(name);
  if (ms) return Number(ms[1]);
  return null;
}

/** Every photo and video in a month's folders, subfolders included, newest first, copies once. */
async function loadMonth(conn: Conn, folders: string[]): Promise<Item[]> {
  const out: Item[] = [];
  async function collect(id: string, depth: number) {
    const kids = await browse(conn, id).catch(() => [] as Item[]);
    for (const k of kids) {
      if (!k.dir) out.push(k);
      else if (depth < 2) await collect(k.id, depth + 1);
    }
  }
  for (const f of folders) await collect(f, 0);
  const seen = new Set<string>();
  const unique = out.filter((i) => {
    const n = nameOf(i.id).toLowerCase();
    if (seen.has(n)) return false;
    seen.add(n);
    return true;
  });
  return unique
    .map((i) => ({ i, t: stampOf(nameOf(i.id)) }))
    .sort((a, b) => (b.t ?? -1) - (a.t ?? -1) || nameOf(b.i.id).localeCompare(nameOf(a.i.id)))
    .map((x) => x.i);
}

const bucketLabel = (key: string) => {
  if (key === 'undated') return 'Undated';
  const [y, m] = key.split('-');
  return m === '00' ? `${y} · month unknown` : `${MONTHS[Number(m) - 1]} ${y}`;
};

/* ------------------------------------------------------------- the feed */

function MonthSection({ conn, bucket, tile, anchor }: {
  conn: Conn; bucket: Bucket; tile: number; anchor?: string;
}) {
  const ref = useRef<HTMLElement>(null);
  const [items, setItems] = useState<Item[] | null>(null);
  const [limit, setLimit] = useState(240);
  const [open, setOpen] = useState<number | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return undefined;
    let live = true;
    const io = new IntersectionObserver((es) => {
      if (!es.some((e) => e.isIntersecting)) return;
      io.disconnect();
      loadMonth(conn, bucket.folders).then((r) => live && setItems(r), () => live && setItems([]));
    }, { rootMargin: '900px' });
    io.observe(el);
    return () => { live = false; io.disconnect(); };
  }, [conn, bucket]);

  if (items && items.length === 0) return null;
  const photos = items?.filter((i) => i.cls === 'image').length ?? 0;
  const videos = items ? items.length - photos : 0;

  return (
    <section ref={ref} id={anchor} style={{ marginBottom: 26, minHeight: items ? undefined : 180, scrollMarginTop: 70 }}>
      <div style={{
        position: 'sticky', top: 0, zIndex: 2, display: 'flex', alignItems: 'baseline', gap: 10,
        padding: '10px 0 8px', background: 'var(--wt-ground)',
      }}>
        <span style={{ fontSize: 18, fontWeight: 300, color: C.text }}>{bucketLabel(bucket.key)}</span>
        {items && (
          <span style={{ fontSize: 12, color: C.faint }}>
            {`${photos} photo${photos === 1 ? '' : 's'}${videos ? ` · ${videos} video${videos === 1 ? '' : 's'}` : ''}`}
          </span>
        )}
      </div>
      {!items ? (
        <div style={{ fontSize: 12, color: C.faint }}>Loading&hellip;</div>
      ) : (
        <>
          <div style={{ display: 'grid', gridTemplateColumns: `repeat(auto-fill, minmax(${tile}px, 1fr))`, gap: 4 }}>
            {items.slice(0, limit).map((m, i) => (
              <Tile key={m.id} conn={conn} item={m} size={tile} onOpen={() => setOpen(i)} />
            ))}
          </div>
          {items.length > limit && (
            <button type="button" onClick={() => setLimit((l) => l + 240)}
              style={{
                display: 'block', margin: '12px auto 0', font: 'inherit', fontSize: 13, padding: '9px 18px',
                borderRadius: 999, cursor: 'pointer', border: `1px solid ${C.line}`, background: 'transparent', color: C.gold,
              }}>
              {`Show ${Math.min(240, items.length - limit)} more from ${bucketLabel(bucket.key)}`}
            </button>
          )}
        </>
      )}
      {open != null && items && (
        <Viewer conn={conn} items={items} index={open} onIndex={setOpen} onClose={() => setOpen(null)} />
      )}
    </section>
  );
}

export function PhotosPage({ hass, narrow }: { hass: Hass; narrow: boolean }) {
  const conn = hass.connection;
  const [buckets, setBuckets] = useState<Bucket[] | null>(null);
  const [error, setError] = useState(false);

  useEffect(() => {
    let live = true;
    buildIndex(conn).then((b) => live && setBuckets(b), () => live && setError(true));
    return () => { live = false; };
  }, [conn]);

  const years = useMemo(() => {
    const seen: string[] = [];
    for (const b of buckets ?? []) {
      const y = b.key.slice(0, 4);
      if (b.key !== 'undated' && !seen.includes(y)) seen.push(y);
    }
    return seen;
  }, [buckets]);

  const jump = useCallback((y: string) => {
    document.getElementById(`photos-${y}`)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }, []);

  const card: CSSProperties = {
    background: C.glass, border: `1px solid ${C.line}`, borderRadius: C.radius, padding: narrow ? 14 : 22, minWidth: 0,
  };

  if (error) {
    return (
      <section style={card}>
        <div style={{ fontSize: 15, marginBottom: 6 }}>The photo library is not available.</div>
        <div style={{ fontSize: 12.5, color: C.dim, lineHeight: 1.6 }}>
          Home Assistant could not open the <b>photos</b> media folder. It needs the NAS share mounted into the
          container (config/bin/ha-photo-mount.sh) and <code>media_dirs: photos</code> in configuration.yaml.
        </div>
      </section>
    );
  }

  const firstOfYear = new Set<string>();
  return (
    <section style={card}>
      <div style={{ display: 'flex', alignItems: 'baseline', gap: 12, marginBottom: 10 }}>
        <span style={{ fontSize: 22, fontWeight: 300 }}>Photos</span>
        <span style={{ fontSize: 12, color: C.faint }}>newest first</span>
      </div>

      {/* Year jump: the feed is long, and "the summer Alex was born" is a year, not a scroll. */}
      {years.length > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: 18 }}>
          {years.map((y) => (
            <button key={y} type="button" onClick={() => jump(y)}
              style={{
                font: 'inherit', fontSize: 12.5, padding: '5px 11px', borderRadius: 999, cursor: 'pointer',
                border: `1px solid ${C.line}`, background: 'rgba(255,255,255,0.04)', color: C.dim,
              }}>{y}</button>
          ))}
        </div>
      )}

      {!buckets ? (
        <div style={{ fontSize: 13, color: C.faint }}>Gathering the library&hellip;</div>
      ) : buckets.map((b) => {
        const y = b.key.slice(0, 4);
        const anchor = b.key !== 'undated' && !firstOfYear.has(y) ? (firstOfYear.add(y), `photos-${y}`) : undefined;
        return <MonthSection key={b.key} conn={conn} bucket={b} tile={narrow ? 84 : 118} anchor={anchor} />;
      })}
    </section>
  );
}
